import{n as e}from"./rolldown-runtime-CbXtAM7H.js";import{r as t,t as n}from"./react-blWa-pWN.js";import{c as r,d as i,f as a,h as o,l as s,m as c,t as l,u,v as d,y as f}from"./index-ButH6ccE.js";var p=e(t(),1),m={id:`annex-order-01`,zone:`annex-order`,title:`A stop outside service`,body:`The direct-channel light opens before the report. M.: ‘Operator. Elevator telemetry is a Facilities concern.’ There is no Facilities extension on the night roster. ‘Yes,’ M. adds. ‘That is what makes this easy. File the fault and do your actual job.’ SECONDARY ORDER — Municipal Annex, car 2. At 00:59:57 the elevator stopped above Floor 11. Service field: FLOOR 12. Requesting operator: your terminal ID. You were not on shift yet.`,choices:[{id:`clear`,label:`Clear it as an out-of-range sensor fault.`,outcome:{text:`The field corrects itself to FLOOR 11 before your confirmation finishes. For one frame, a restricted attachment reads: FIELD VISIT — SENIOR OPERATOR ONLY. ‘Thank you,’ M. says. ‘See? We can have a normal conversation.’ The direct channel closes before you can answer.`,qualities:{Routine:1,Salary:2}},completeZone:!0},{id:`trace`,label:`Trace the request before filing it.`,outcome:{text:`The request carries your terminal ID, your timestamp format, and a signature shaped like yours. The direct-channel light is still on. ‘That is not a question you need answered,’ M. says. A pause. ‘For what it is worth, I also dislike that signature.’ The attachment ends at a clearance seal: SENIOR OPERATOR. A new line appears in your file: PROMOTION REVIEW ACTIVE.`,qualities:{Doubt:1,Perception:1,Attention:1}},completeZone:!0}]},h={id:`breakroom-01`,zone:`breakroom`,title:`MUNICIPAL BREW`,body:`The machine is older than the building, or wants to be. Its label says MUNICIPAL BREW — SERVICE NOT REQUIRED. Your grounds fit the drawer. The system's coffee is always warm; yours is warm because you made it. This is a difference you are still allowed to keep.`,choices:[{id:`drink`,label:`Make a cup. Drink it here.`,outcome:{text:`It tastes like the city is not in the room for a minute. The machine hums, satisfied, like it has been waiting for a competent operator.`,qualities:{Routine:1,Salary:1}},endZone:!0},{id:`watch`,label:`Make a cup. Watch the pot warm.`,outcome:{text:`The heating coil glows like a small, patient sun. Somewhere below, the building adjusts itself around the warmth. You are the only one who notices.`,qualities:{Perception:1,Attention:1}},endZone:!0},{id:`leave`,label:`Leave it. The system's coffee is fine.`,outcome:{text:`It is always fine. That is the problem.`,qualities:{Doubt:1}},endZone:!0}]},g={id:`custodial-01`,zone:`custodial-stores`,title:`The memo about the fence`,body:`Custodial says the bolt cutters are out. You hold them. They are heavy and patient and older than the building. The memo about the annex fence — the one that says the fence is not there — is pinned above the shelf where they were not.`,choices:[{id:`memo`,label:`Read the memo twice.`,outcome:{text:`THE ANNEX SUB-BASEMENT ACCESS FENCE HAS BEEN REMOVED. NO FENCE EXISTS AT THIS LOCATION. The staples are fresh. The fence is not there. The cutters are in your hand.`,qualities:{Doubt:1,Perception:1}},endZone:!0},{id:`back`,label:`Put them back. For now.`,outcome:{text:`You put them back. The shelf takes them like a drawer taking a key. You will need them later. Something will need them.`,qualities:{Perception:1,Attention:1}},endZone:!0}]},_={id:`sticky-01`,zone:`day-crew-notes`,title:`THE NIGHT OPERATOR SEEMS… FAMILIAR.`,body:`A yellow note on the memo board, between a reminder about the fourth-floor printer and a lunch rotation nobody has filled in. Day-crew handwriting, unhurried, lowercase: the night operator seems... familiar. i can't place him. — D. The note is dated today. You are the night operator. There is no photograph of you on any wall. The day crew left this at 16:00, while you were somewhere the log says you were not.`,choices:[{id:`read`,label:`Read it twice.`,outcome:{text:`The second reading is worse. The note is dated today, in a hand that predates the building's coffee — and under the first line, fainter, almost erased: do not ask him how long he has worked here. Someone in the day crew already knows the answer and does not want it said out loud.`,qualities:{Perception:1,Attention:1}},next:`sticky-02`},{id:`leave`,label:`Leave it for them.`,outcome:{text:`You leave it. It is about you, and you are not ready to be a topic. The yellow square glows in the dark of the office like a small, patient sun. Tomorrow it will say something else.`,qualities:{Routine:1,Salary:1}},endZone:!0}]},v={id:`sticky-02`,zone:`day-crew-notes`,title:`IT'S THE HANDWRITING.`,body:`A new note, added since the last time you looked. Same hand, faster now: it's the handwriting. i matched it against the old operator files. his signature is all over the 2019 forms. ask him who trained him. — D. There is no old operator in the roster. There is no 2019. The handwriting is the same as yours — right down to the way you cross your sevens.`,choices:[{id:`take`,label:`Take the note. Keep it.`,outcome:{text:`It comes away clean, like a page that has been waiting to be removed. You fold it into your logbook. The board looks wrong without it — a gap where something alive used to be. The day crew will write another. They have been writing them for years.`,qualities:{Doubt:1,Perception:1}},next:`sticky-03`},{id:`leave`,label:`Leave it. The day crew watches the building, not you.`,outcome:{text:`You leave it. The note is about the building's memory, not about you — which is worse. Someone in the day crew has been reading old operator files, and the old operator signs the way you do.`,qualities:{Routine:1,Attention:1}},endZone:!0}]},y={id:`sticky-03`,zone:`day-crew-notes`,title:`BEFORE I WAS BORN.`,body:`The last note is in a different hand — older, formal, the pen pressed hard: my father trained under the night operator. my father is sixty-two. the night operator looks thirty. ask him what he eats. — P. Someone has written underneath, in the first hand, smaller: don't. i already asked. The note is not dated. The paper has the soft, worn feel of a page that has been folded for decades and only now left out where a night operator could find it.`,choices:[{id:`copy`,label:`Copy both notes into your logbook.`,outcome:{text:`You copy them word for word, including the correction. The logbook is the only record the city cannot revise. When you look up, the board is clean — the notes are gone, and you do not remember them being taken, and the coffee is warm, and the clock says 01:00, and the logbook does not forget.`,qualities:{Doubt:1,Perception:1,Attention:1}},completeZone:!0},{id:`tear`,label:`Tear them down. They are wrong about you.`,outcome:{text:`You tear them down. The shreds go in the bin; the bin is empty by morning. They are wrong about you — you are thirty, you are not thirty, you do not remember being hired. The day crew will write new notes about the night operator who reads the board.`,qualities:{Routine:1,Attention:1}},completeZone:!0}]},b={id:`doorman-01`,zone:`doorman`,title:`The lobby at 02:00`,body:`The Annex doorman is not on the roster. The memo says he does not exist. He is in the lobby at 02:00, reading a paper that is always Tuesday's. You set the box of morning smokes on the counter. He does not look up, but the paper shifts, and the counter — the counter breathes out.`,choices:[{id:`ask`,label:`Ask about the twelfth floor.`,outcome:{text:`The paper does not move for a long time. Then: "The elevator knows the way, sir. The elevator has always known the way. The building just doesn't like to admit it." He folds the paper. It is Tuesday's. It is always Tuesday's.`,qualities:{Doubt:1,Perception:1}},endZone:!0},{id:`leave`,label:`Just leave the box.`,outcome:{text:`You leave it. On your way out, the paper has moved to the floor below his hands, and the counter is breathing evenly, like something that has been given what it wanted.`,qualities:{Routine:1,Attention:1}},endZone:!0}]},x={id:`floor12-01`,zone:`floor12`,title:`The blank button`,body:`The annex at night. The elevator panel has eleven numbers and a warmth where a twelfth would be. A work order in your pocket is the only key the map does not have. The service channel clicks. ‘Operator,’ M. says, less formally than the memos. ‘Elevators develop aspirations. We do not encourage them. Your job description ends at eleven.’`,choices:[{id:`press`,label:`Press the warmth.`,outcome:{text:`‘I was hoping you would be more boring,’ M. says. The car rises past 11 without slowing. The display still says 11. The doors are thinking about it.`,qualities:{Attention:2,Doubt:1}},next:`floor12-02`},{id:`leave`,label:`Take the stairs back to the desk. Not tonight.`,outcome:{text:`‘Good,’ M. says too quickly. ‘That was almost a conversation.’ The work order is still in your pocket. The zone will wait. The system prefers that.`,qualities:{Routine:1}},endZone:!0}]},S={id:`floor12-02`,zone:`floor12`,title:`Wrong doors`,body:`The hallway is the eleventh-floor hallway, except the numbers run 1201, 1202, 1203. The carpet is the same carpet. The exit signs point at each other. Through the end window, the hoverlanes should be visible — instead there is a flat amber wash, like the city rendered its skybox too close and forgot to add distance.`,choices:[{id:`1207`,label:`Find 1207. That's the work order.`,outcome:{text:`1207 is a records room. The door is unlocked. Smoke, faint, like a file that has been thinking about burning for a long time. The window in there shows the same amber wash, but thinner, as if the glass is tired.`,qualities:{Perception:1,Attention:1}},next:`floor12-03`}]},C={id:`floor12-03`,zone:`floor12`,title:`The records room`,body:`Cabinets to the ceiling. Every drawer labelled TUESDAY. In the middle of the room: a desk, a form, a pen. The form already has your name. The signature line is blank.`,choices:[{id:`read`,label:`Read the form.`,outcome:{text:`REASON FOR TERMINATION: — the rest is still being written, in a hand that looks like yours if you were in a hurry.`,qualities:{Doubt:1,Attention:1}},next:`floor12-04`}]},w={id:`floor12-04`,zone:`floor12`,title:`The fire`,body:`The smoke was not a metaphor. A cabinet labelled TUESDAY catches. The sprinklers do not. The form on the desk does not burn. Recommended: do not proceed. — M.`,choices:[{id:`through`,label:`Go through the smoke. The form is the point.`,outcome:{text:`Heat like a server room. On the other side of the fire: an office that is your office, and someone already sitting in your chair.`,qualities:{Attention:2,Doubt:1}},next:`floor12-05`},{id:`retreat`,label:`Retreat. Take the stairs. The memo was right.`,outcome:{text:`You leave with ash on your cuffs and a key that was in the work-order envelope. The map does not have a lock for it. Floor 12 will close behind you, for now.`,qualities:{Perception:1}},completeZone:!0}]},T={id:`floor12-05`,zone:`floor12`,title:`The Auditor`,body:`It is holding a form with your name on it. The form is already signed. Its face is a blur of badges. The chair it sits in is yours. Recommended: do not proceed. — M.`,choices:[{id:`forward`,label:`Step forward. Ask whose signature that is.`,outcome:{text:`It turns the form around. The signature is yours. You have not signed it yet. The lights go.`,qualities:{Attention:3,Doubt:1}},next:`floor12-06`,death:!0},{id:`back`,label:`Do not proceed. Take the key. Leave.`,outcome:{text:`The Auditor does not follow. In the envelope: the NULL KEY — a key the map doesn't have. You are still alive to file it.`,qualities:{Perception:1}},completeZone:!0}]},E={id:`floor12-06`,zone:`floor12`,title:`Black`,body:`You do not remember the interval. You remember a ledger. You remember three discrepancies and a polite request to reconcile them. You remember saying yes, because there was no other form.`,choices:[{id:`wake`,label:`Wake at shift start. Write it down.`,outcome:{text:`The morning memo thanks staff for a quiet, incident-free week. Nobody remembers the fire. You do. In your pocket: the NULL KEY. Day 1 (again). There is no Building 7.`,qualities:{Doubt:2,Perception:1}},completeZone:!0}]},D={id:`handwritten-01`,zone:`handwritten-order`,title:`FILED FROM THE NIGHT DESK`,body:`A work order, timestamped 03:12, filed from your terminal. REPLACE STREETLIGHT 4-B, SECTOR 9. SIGNED: [your name], NIGHT OPERATOR. The signature is yours — the same tilt, the same crossing, the same habit of underlining the first letter. You were at the terminal at 03:12. The queue has no memory of this order. The queue is certain it has no memory. It is still in the tray, warm, like the coffee, like something held a moment ago.`,choices:[{id:`compare`,label:`Hold it. Compare the signature.`,outcome:{text:`You hold your logbook beside it. The match is exact — including the correction you made to your own signature yesterday, after M. complained it was illegible. Whoever wrote this saw the corrected page. Nobody sees the corrected page. The corrected page is between your hands, and the copy is already filed.`,qualities:{Perception:1,Attention:1}},next:`handwritten-02`},{id:`file`,label:`File it with the night backlog. Say nothing.`,outcome:{text:`You file it. It counts. The system pays for work you did not do, filed under your own hand, and the credits land like a coin in a pocket that was already warm. Somewhere in the ledger, a row with your name on it balances itself a little better.`,qualities:{Routine:1,Salary:3}},completeZone:!0}]},O={id:`handwritten-02`,zone:`handwritten-order`,title:`THE SAME HAND`,body:`The comparison is done. The order was written by the same hand that writes your logbook — which means the handwriting is not like yours. It is yours. There is a second signature on the back, smaller, in the margin: a name that is almost yours, with one letter different, as if someone stopped halfway through forging a life. The light in the tray is the same amber as the light on the floor that does not exist.`,choices:[{id:`keep`,label:`Keep it. It is evidence.`,outcome:{text:`It goes into your logbook, folded with the yellow notes. Evidence, you tell yourself. Evidence is only evidence if you survive to file it. The order stays warm against your ribs, and the second signature reads like a warning, and you write down the date anyway.`,qualities:{Doubt:1,Perception:1}},completeZone:!0},{id:`burn`,label:`Burn it. Whatever wrote it can write another.`,outcome:{text:`You burn it in the break-room machine's heat, like the system would want. The smoke smells like paper, and like something else — like a file closing itself. The tray is empty. The desk is clean. Somewhere, a hand that is yours is already warming the next sheet.`,qualities:{Routine:1,Attention:1}},completeZone:!0}]},k={id:`interim-deep-01`,zone:`interim-deep`,title:`The open frame`,body:`The next shift has not begun. The gap is a narrow hall lit by the number 06:00:00, repeated until it becomes a wall.`,choices:[{id:`enter`,label:`Enter the open frame.`,outcome:{text:`Your footsteps arrive before you do. A file drawer opens somewhere ahead.`,qualities:{Doubt:1}},next:`interim-deep-02`},{id:`call`,label:`Call for the Cleaner.`,outcome:{text:`A mop appears first. Then a voice says, “You are early.”`,qualities:{Perception:1}},next:`interim-deep-02`}]},A={id:`interim-deep-02`,zone:`interim-deep`,title:`The audit`,body:`The Auditor sits at a desk assembled from terminated forms. Seven discrepancies wait beneath a blank signature.`,choices:[{id:`read`,label:`Read the discrepancies.`,outcome:{text:`They are not mistakes. They are seven versions of the same decision, each filed by someone with your hands.`,qualities:{Doubt:1}},next:`interim-deep-03`},{id:`sign`,label:`Sign the blank line.`,outcome:{text:`The pen refuses ink. The Auditor looks disappointed in a way that feels practiced.`,qualities:{Attention:1}},next:`interim-deep-03`}]},j={id:`interim-deep-03`,zone:`interim-deep`,title:`The Cleaner`,body:`The Cleaner has no face in the gap. He offers a small power source and asks whether you intend to repair the city or leave it honest.`,choices:[{id:`ask`,label:`Ask what honest means.`,outcome:{text:`“It means it stops agreeing with itself.” He puts the component on the desk.`,qualities:{Perception:1}},next:`interim-deep-04`},{id:`take`,label:`Take the component without asking.`,outcome:{text:`The Cleaner nods. “That is also an answer.” The component is cold enough to burn.`,qualities:{Doubt:1}},next:`interim-deep-04`}]},ee={id:`interim-deep-04`,zone:`interim-deep`,title:`The sixth piece`,body:`The INTERIM component is a piece of the missing second between shifts. It pulses when you remember dying.`,choices:[{id:`take`,label:`Take the INTERIM component.`,outcome:{text:`The hall closes. You wake at the next shift with six pieces in your file and one question the system cannot phrase.`,qualities:{Doubt:1}},completeZone:!0},{id:`return`,label:`Return it to the gap.`,outcome:{text:`The Cleaner puts it in your hand again. “You will need the hour.” The hall closes behind you.`,qualities:{Perception:1}},completeZone:!0}]},te={id:`night-radio-01`,zone:`night-radio`,title:`Receiving`,body:`Dispatch's radio license ends at 03:00. Your permit runs to 06:00, which is where the fine print begins: THIS PERMIT DOES NOT AUTHORIZE RECEIVING. You plug in anyway, after the third task, and the channel is not empty.`,choices:[{id:`listen`,label:`Listen.`,outcome:{text:`A voice, faint, counting. Not dispatch's dispatchers. Not the day crew. Someone is counting streets, and when they reach forty-one thousand three hundred and twelve they start again.`,qualities:{Doubt:1,Perception:1}},endZone:!0},{id:`transmit`,label:`Transmit.`,outcome:{text:`The counting stops. A long pause. Then, very clearly, a voice you almost know: "...again, Operator?" The channel goes to static. It stays static.`,qualities:{Doubt:1,Attention:1}},endZone:!0},{id:`off`,label:`Switch it off. The permit says receiving.`,outcome:{text:`You file the permit. The fine print is very clear. The counting continues, quietly, in the wiring.`,qualities:{Routine:1}},endZone:!0}]},ne={id:`off-map-sectors-01`,zone:`off-map-sectors`,title:`Beyond nine`,body:`VANTABLACK does not ask where you are going. Past Sector 9, the road loses its painted edges and the headlights illuminate wireframe.`,choices:[{id:`continue`,label:`Tell VANTABLACK to continue.`,outcome:{text:`The cab keeps moving after the road ends. The dispatch clock loses three seconds.`,qualities:{Doubt:1}},next:`off-map-sectors-02`},{id:`stop`,label:`Tell VANTABLACK to stop.`,outcome:{text:`The cab stops. The map continues without it. VANTABLACK says, “We have done this before.”`,qualities:{Perception:1}},next:`off-map-sectors-02`}]},re={id:`off-map-sectors-02`,zone:`off-map-sectors`,title:`The empty houses`,body:`The sectors contain houses with no interiors. In one window, a desk lamp is on. Its light falls toward you instead of the floor.`,choices:[{id:`enter`,label:`Open the nearest door.`,outcome:{text:`There is a copy of the night desk inside, including the cup you left beside the console.`,qualities:{Attention:1}},next:`off-map-sectors-03`},{id:`pass`,label:`Keep driving.`,outcome:{text:`The houses turn their blank windows as you pass. VANTABLACK stops using the radio.`,qualities:{Doubt:1}},next:`off-map-sectors-03`}]},ie={id:`off-map-sectors-03`,zone:`off-map-sectors`,title:`Operator 5`,body:`A road sign reads OPERATOR 5 — NEXT LEFT. VANTABLACK says the sign is not for you. The voice comes from the back seat.`,choices:[{id:`turn`,label:`Take the turn.`,outcome:{text:`The back seat is empty, but a memory card is buckled in. Its label is your employee number.`,qualities:{Perception:1}},next:`off-map-sectors-04`},{id:`straight`,label:`Stay on the road.`,outcome:{text:`The sign changes to OPERATOR 5 — TOO LATE. The memory card is waiting in the glove box.`,qualities:{Doubt:1}},next:`off-map-sectors-04`}]},ae={id:`off-map-sectors-04`,zone:`off-map-sectors`,title:`The copy`,body:`The CHIP contains a recording of your first orientation. Under it is a second recording: the moment before it.`,choices:[{id:`take`,label:`Take the CHIP and return.`,outcome:{text:`VANTABLACK finds the road at 05:59:58. The city renders around the cab, relieved.`,qualities:{Doubt:1}},completeZone:!0},{id:`erase`,label:`Erase the second recording.`,outcome:{text:`The first recording changes too. You keep the CHIP because the copy is the point.`,qualities:{Perception:1}},completeZone:!0}]},oe={id:`records-basement-01`,zone:`records-basement`,title:`The stairwell`,body:`The lift refuses to acknowledge the basement. The stairs continue below the foundations, past a sign that says MUNICIPAL MEMORY — KEEP DRY.`,choices:[{id:`descend`,label:`Take the stairs.`,outcome:{text:`The air below tastes of paper and rain.`,qualities:{Doubt:1}},next:`records-basement-02`},{id:`return`,label:`Leave the sign where it is.`,outcome:{text:`The sign acquires your name in pencil. You leave anyway.`,qualities:{Routine:1}},endZone:!0}]},se={id:`records-basement-02`,zone:`records-basement`,title:`The address row`,body:`A clerk has left a ledger open. Every address is written twice: once for the building, once for the version of the building Meridian currently permits.`,choices:[{id:`compare`,label:`Compare the two rows.`,outcome:{text:`The second address is your desk. The first is somewhere the city has deleted.`,qualities:{Perception:1}},next:`records-basement-03`},{id:`close`,label:`Close the ledger.`,outcome:{text:`The pages close around a missing street. Something below you exhales.`,qualities:{Attention:1}},next:`records-basement-03`}]},ce={id:`records-basement-03`,zone:`records-basement`,title:`The eraser`,body:`The basement wall is covered in crossed-out districts. Behind the newest mark is a lens-shaped piece of glass, set into the ledger like an eye.`,choices:[{id:`remove`,label:`Lift the eraser from the page.`,outcome:{text:`The erased district returns for one breath. You see its streetlights, and the edge of the source beneath them.`,qualities:{Doubt:1}},next:`records-basement-04`},{id:`observe`,label:`Read without touching.`,outcome:{text:`The mark changes from a line to a warning. You understand why the clerk wore gloves.`,qualities:{Perception:1}},next:`records-basement-04`}]},le={id:`records-basement-04`,zone:`records-basement`,title:`The source note`,body:`At the bottom of the ledger: SOURCE OF TRUTH — DO NOT COPY. The warning is underlined in your handwriting.`,choices:[{id:`take`,label:`Take the LENS and file the note.`,outcome:{text:`The basement files itself. A clean page remains where your name was. You carry the eye upstairs.`,qualities:{Doubt:1}},completeZone:!0},{id:`refuse`,label:`Leave the LENS in the ledger.`,outcome:{text:`The city can keep one eye closed. You cannot. The glass is in your pocket when you reach the stairs.`,qualities:{Perception:1}},completeZone:!0}]},M={id:`restricted-01`,zone:`restricted-files`,title:`The drawer`,body:`The drawer beside the roster desk has no handle. It has never needed one. The lock is a clearance, and yours now clears it. You pull, and the drawer comes out like a breath held too long. Inside: one folder. PATCH NOTES, WEEK 41. The staples are warm.`,choices:[{id:`read`,label:`Read the patch notes.`,outcome:{text:`The folder opens. The pages are numbered the way a city would number its weeks: 41, 41, 41.`,qualities:{Doubt:1}},next:`restricted-02`},{id:`close`,label:`Close the drawer.`,outcome:{text:`You close it. The drawer settles, satisfied, like a mouth that has been fed a secret. You will be back. The drawer knows you will be back.`,qualities:{Doubt:1}},endZone:!0}]},N={id:`restricted-02`,zone:`restricted-files`,title:`Patch notes, week 41`,body:`REVISIONS, WEEK 41: The population chart will display 41,312 (no change). Break-room coffee will be warm on arrival (no change). Building 7 basement light fixture: removed (no fixture existed). Elevator car 2 service range: amended to eleven floors (previous range: eleven floors, amended). The twelfth floor — the entry is scratched out so hard the paper is thin. Beneath the scratch, in a hand that is not the typist's: it is still there. We know. We filed it anyway. In the corner of the page, an audit stamp: VERIFIED. The ink is still wet.`,choices:[{id:`memorise`,label:`Memorise the page.`,outcome:{text:`You read it until the words are yours. The page does not change. But the paper is thinner where the twelfth floor is, and now you know the thinness by heart.`,qualities:{Perception:1,Doubt:1}},endZone:!0},{id:`file`,label:`File it under MEMORANDA.`,outcome:{text:`You file it. The drawer takes it back. Somewhere, a ledger line adjusts itself to include you in the count — 41,313 — and then, politely, corrects itself.`,qualities:{Routine:1,Attention:1}},endZone:!0}]},P={id:`rooftop-array-01`,zone:`rooftop-array`,title:`The roof door`,body:`The permit unlocks the roof, but the door opens onto a different hour. Rain falls upward beyond the threshold.`,choices:[{id:`step`,label:`Step outside with the thermos.`,outcome:{text:`The rain remembers gravity when you do. The antennas begin their nightly test.`,qualities:{Attention:1}},next:`rooftop-array-02`},{id:`wait`,label:`Wait for the test to finish.`,outcome:{text:`The test tone says your name in a voice made of weather. You open the door.`,qualities:{Doubt:1}},next:`rooftop-array-02`}]},F={id:`rooftop-array-02`,zone:`rooftop-array`,title:`The dead channel`,body:`Six antennas point inward. The seventh points past the smog at a black patch where stars should be.`,choices:[{id:`tune`,label:`Tune the radio permit to the black patch.`,outcome:{text:`Static resolves into a distant room: a chair, a desk, someone waiting for a reply.`,qualities:{Perception:1}},next:`rooftop-array-03`},{id:`record`,label:`Record the test tone.`,outcome:{text:`The recording contains a second operator breathing between every note.`,qualities:{Doubt:1}},next:`rooftop-array-03`}]},I={id:`rooftop-array-03`,zone:`rooftop-array`,title:`Carrier`,body:`The carrier is not a broadcast. It is a handshake. The roof asks for an acknowledgement and lights the antenna beneath your feet.`,choices:[{id:`answer`,label:`Acknowledge the carrier.`,outcome:{text:`Something outside the weather loop answers. The roof becomes very interested in your exact location.`,qualities:{Attention:1}},next:`rooftop-array-04`},{id:`decline`,label:`Do not answer.`,outcome:{text:`The handshake completes anyway. The city has been answering on your behalf for years.`,qualities:{Doubt:1}},next:`rooftop-array-04`}]},L={id:`rooftop-array-04`,zone:`rooftop-array`,title:`The oscillator`,body:`Inside the antenna housing, a crystal vibrates at the frequency of the outside room. It is almost warm.`,choices:[{id:`take`,label:`Remove the CRYSTAL.`,outcome:{text:`The smog becomes a flat grey wall. In your thermos, the coffee is briefly cold. You have the signal.`,qualities:{Doubt:1}},completeZone:!0},{id:`hold`,label:`Hold the housing open and listen.`,outcome:{text:`The outside room says: We can hear you. You take the CRYSTAL before the roof can close.`,qualities:{Perception:1}},completeZone:!0}]},R={id:`routine-01`,zone:`routine`,title:`Building 7, basement light`,body:`Work order, timestamp 02:14:07, coffee stain in the corner. Third report this week. There is no Building 7 on the map, but the window shows its roof where no roof should be — a flat dark square catching neon that has no business reaching it. The stain is still wet.`,choices:[{id:`file`,label:`File it. There is no Building 7.`,outcome:{text:`The system replies, instantly: the ticket does not exist. It is in your hand. Outside, the dark square catches another slow sweep of amber and pretends it was never there.`,qualities:{Routine:1,Salary:2}},endZone:!0},{id:`cross`,label:`Cross-reference the address.`,outcome:{text:`The annex directory has a gap between 6 and 8. Someone has erased a line. The paper is thinner there — the same thinness as the light on that roof when the cutter passes.`,qualities:{Perception:1,Attention:1}},endZone:!0}]},z={id:`routine-02`,zone:`routine`,title:`Population chart`,body:`41,312. Holding steady. The chart goes back one hundred years, to the day. Every year: 41,312. No births. No deaths. No one moved.`,choices:[{id:`initial`,label:`Initial the chart. Move on.`,outcome:{text:`Your initials look like last Tuesday's initials. You tell yourself you have a consistent signature.`,qualities:{Routine:1,Salary:2}},endZone:!0},{id:`count`,label:`Count them. Just this once.`,outcome:{text:`You get to 41,311 and the last name is yours. You do not remember writing it there.`,qualities:{Doubt:1,Attention:1}},endZone:!0}]},B={id:`routine-03`,zone:`routine`,title:`Eleven floors`,body:`The memo board: Reminder — the Municipal Annex has eleven (11) floors. Any employee reporting a twelfth (12th) floor should be referred to HR. — M.`,choices:[{id:`obey`,label:`Refer yourself to no one. It's eleven.`,outcome:{text:`Eleven. You can count to eleven. The elevator panel agrees, tonight.`,qualities:{Routine:1,Salary:1}},endZone:!0},{id:`press`,label:`Walk to the elevator. Look for a twelfth button.`,outcome:{text:`There is a blank where 12 would be. It is slightly warmer than the panel around it.`,qualities:{Perception:1,Attention:1}},endZone:!0}]},V={id:`routine-04`,zone:`routine`,title:`On-time performance`,body:`All trucks on schedule. On-time performance: 100.0%. It has never been 99.9. You are invited to be proud of this. Outside, the hoverlanes keep their river of light under the limit — or just over it — and the city’s compliance looks beautiful from this high. Inside, the stamp is the only proof it happened.`,choices:[{id:`proud`,label:`Be proud. Stamp 100.0%.`,outcome:{text:`The stamp is worn in the shape of those digits. No other stamp exists in the drawer. Through the window, a cutter passes without hurry — nothing to chase, nothing out of place. The number remains perfect.`,qualities:{Routine:1,Salary:2}},endZone:!0}]},H={id:`routine-05`,zone:`routine`,title:`VANTABLACK`,body:`Roll call. VANTABLACK again — or is it VANTABLUE tonight? The letters on the sheet have been written over. The radio is waiting. Through the window, the night asphalt of Sector 9 holds a single pair of tail-lights where the map says no road goes. He is already out there.`,choices:[{id:`copy`,label:`Copy. Keep it moving.`,outcome:{text:`"Copy." He does not say all clear. He does not say anything else. The tail-lights hold, then ease forward into a street that will not be on your next work order.`,qualities:{Routine:1,Salary:1}},endZone:!0},{id:`name`,label:`Use the name on the sheet, whatever it is.`,outcome:{text:`You say it. He laughs, once, like a man who has heard his own eulogy. "Again, Operator?" The tail-lights dip — as if the car smiled — and the radio ticks with the wind between towers.`,qualities:{Doubt:1,Perception:1,Attention:1}},endZone:!0}]},U={id:`routine-06`,zone:`routine`,title:`File the backlog`,body:`A stack of tickets that are all the same ticket. The system likes it when you file them. The system pays you when you file them. The coffee is still warm.`,choices:[{id:`file`,label:`File the backlog. Get paid.`,outcome:{text:`Salary posted. Attention cools a degree you cannot see. The stack is the same height as when you started.`,qualities:{Salary:5,Routine:1,Attention:-1}},endZone:!0}]},W={id:`utility-closet-01`,zone:`utility-closet`,title:`The third fuse box`,body:`The closet behind the break room is on no plan. The lock is a latch. Inside: mops that have never dried, a fuse box labelled with a floor that does not exist, and a second labelled with the floor you are standing on. Your torch shows a third fuse box, behind the first two, painted over. It is warm.`,choices:[{id:`open`,label:`Open the painted box.`,outcome:{text:`Inside: a single fuse, stamped 1207. It is not connected to anything. It is not a fuse. You put it back. It was warm.`,qualities:{Doubt:1,Perception:1}},endZone:!0},{id:`close`,label:`Close the closet. Latch it.`,outcome:{text:`The latch clicks. The closet is a closet again. You hear, behind the door, one soft knock. Just the one.`,qualities:{Routine:1,Attention:1}},endZone:!0}]},ue={id:`vent-network-01`,zone:`vent-network`,title:`The grille`,body:`The maintenance grille is painted the exact colour of the wall. The bolt heads are newer than the building and warmer than the room.`,choices:[{id:`cut`,label:`Use the bolt cutters.`,outcome:{text:`The grille opens onto a corridor that was rendered after the wall around it.`,qualities:{Doubt:1}},next:`vent-network-02`},{id:`listen`,label:`Put your ear to the grille.`,outcome:{text:`A pen scratches on the other side. It stops when you breathe.`,qualities:{Perception:1}},next:`vent-network-02`}]},de={id:`vent-network-02`,zone:`vent-network`,title:`Between walls`,body:`The crawlspace carries old dispatch audio. Operator 5 is reading tomorrow's queue, then whispering numbers that do not fit any route.`,choices:[{id:`follow`,label:`Follow the numbers.`,outcome:{text:`They lead to a junction labelled PATCH SCAR 03. The label has been pried open.`,qualities:{Perception:1}},next:`vent-network-03`},{id:`mark`,label:`Mark the wall and continue.`,outcome:{text:`Your chalk mark appears ahead of you first. The corridor has started taking shortcuts.`,qualities:{Doubt:1}},next:`vent-network-03`}]},fe={id:`vent-network-03`,zone:`vent-network`,title:`The junction`,body:`Three cables cross the junction: one for power, one for weather, one that hums when you think about leaving.`,choices:[{id:`trace`,label:`Trace the humming cable.`,outcome:{text:`It terminates in a maintenance box containing a coil of impossible copper.`,qualities:{Attention:1}},next:`vent-network-04`},{id:`sever`,label:`Cut the quietest cable.`,outcome:{text:`The weather above stops for a second. The city notices, then pretends not to.`,qualities:{Doubt:1}},next:`vent-network-04`}]},pe={id:`vent-network-04`,zone:`vent-network`,title:`A bridge`,body:`The coil is labelled WIRE. Its insulation is made from narrow strips of old operator logs. The last strip says: DO NOT LET IT COMPLETE THE CIRCUIT.`,choices:[{id:`take`,label:`Take the WIRE.`,outcome:{text:`The vent network folds into an ordinary service duct. Your map now has one route the city cannot redraw.`,qualities:{Doubt:1}},completeZone:!0},{id:`read`,label:`Read the last strip first.`,outcome:{text:`The warning is not addressed to you. It is signed by whoever is currently holding the WIRE.`,qualities:{Perception:1}},completeZone:!0}]},me={id:`window-ledge-01`,zone:`window-ledge`,title:`The courtyard`,body:`The break-room window faces the courtyard. With your thermos full, you can stand here the way the system intends nobody to stand: comfortable, unhurried, looking out. The courtyard has a fence that appears on no plan. It is the same fence.`,choices:[{id:`count`,label:`Count the windows across.`,outcome:{text:`The annex, from here, has eleven floors of windows. You count twelve rows before your eyes stop cooperating. The twelfth row is dark. It is always dark. It is always there.`,qualities:{Doubt:1,Perception:1}},endZone:!0},{id:`sip`,label:`Sip. Watch the courtyard.`,outcome:{text:`Nothing happens. Nothing needs to. For a minute the city forgets to be strange, and you let it. The thermos stays warm longer than the building's coffee ever has.`,qualities:{Routine:1}},endZone:!0}]},G=[`annex-order`,`handwritten-order`,`routine`,`day-crew-notes`,`floor12`,`restricted-files`,`breakroom`,`night-radio`,`utility-closet`,`custodial-stores`,`window-ledge`,`doorman`,`records-basement`,`vent-network`,`rooftop-array`,`off-map-sectors`,`interim-deep`],he=new Set([`id`,`zone`,`title`,`body`,`choices`]),ge=new Set([`id`,`label`,`outcome`,`next`,`endZone`,`completeZone`,`death`]),_e=new Set([`text`,`qualities`]),K=cla